def validate_mirror_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != MIRROR_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm/lags/mirror 与 mirror 契约
    # 一致，复用其全量校验
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
    ) = validate_mirror_config(
        {key: config[key] for key in MIRROR_CONFIG_KEYS}
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return (
        bridges, links, delay, bridge, ports, age, storm, lags, mirror,
        max_frame,
    )


